import{_ as t,o,c as u,ag as e}from"./chunks/framework.DaAXJYxM.js";const d=JSON.parse('{"title":"第76章 请假","description":"","frontmatter":{},"headers":[],"relativePath":"第76章_请假.md","filePath":"第76章_请假.md"}'),a={name:"第76章_请假.md"};function q(_,p,r,n,s,c){return o(),u("div",null,[...p[0]||(p[0]=[e('<h1 id="第76章-请假" tabindex="-1">第76章 请假 <a class="header-anchor" href="#第76章-请假" aria-label="Permalink to &quot;第76章 请假&quot;">​</a></h1><p>十月十四号，她跟我说她要请假。</p><p>她说，我阿婆中风了。</p><p>我说，严重吗。</p><p>她说，现在在 ICU 外面，还没进去，人叫不醒。</p><p>我说，那你怎么办。</p><p>她说，我买票。</p><p>我说，你这边不是不能回。</p><p>她说，我回。</p><p>我说，你那实习。</p><p>她说，我请两周。</p><p>我说，你请两周他们不留你。</p><p>她那边隔了一会儿。</p><p>她说，那就不留。</p><p>她说，我买哪一班。</p><p>我说，你别管钱。</p><p>她说，我知道。</p><p>我说，你知道什么。</p><p>她说，你说&quot;你别管钱&quot;的时候，你是在说你现在管不了。</p><p>她说，我自己算过了。</p><p>她说，一万二。</p><p>她说，我卡上有九千，剩下的我找何叶借。</p><p>我看到&quot;找何叶借&quot;这一句，心里很不是滋味。</p><p>因为我知道她这个人一辈子不借钱。</p><p>高一她跟我说过一句：我这辈子开口跟人要钱只有一次，那次我难受了一个月。</p><p>现在她第二次开口，是为了回去看一个不认识她的人。</p><p>那天下午她一直没上线。</p><p>六点她发了一张机场的照片。</p><p>她说，我提早三个小时到。</p><p>她说，我不敢回宿舍，我一回去我就想我不去了。</p><p>我说，你去吧。</p><p>她说，你讲这句话讲得这么轻。</p><p>我说，我讲重了你要改主意？</p><p>她说，我不会改。</p><p>她说，我就是听不得你说&quot;去吧&quot;。</p><p>她说，你说&quot;去吧&quot;这两个字，我就想到我妈。</p><p>她说，我妈那年跟我说&quot;你去吧&quot;，是让我去念那个我不念的专业。</p><p>她说，我现在一听见&quot;去吧&quot;我就想，我又在让一个人走。</p><p>我说，那我说什么。</p><p>她说，你说&quot;我在这儿&quot;。</p><p>我坐在那儿。</p><p>我说，我在这儿。</p><p>她发了一个很难看的表情。</p><p>她说，行了。</p><p>她说，我登机了。</p><p>她在路上的那二十个小时，我一条也没发。</p><p>不是我不想发。</p><p>是因为我算了一下：我这边发的每一条，她那边落地以后是一堆她没回的消息。</p><p>而她那边现在没有心情还这一堆。</p><p>我这边夜里三点，她那边应该是傍晚。</p><p>我在床上躺着听呼噜。</p><p>第二天她上线是十月十六号，她那边下午四点。</p><p>她说，我到了。</p><p>我说，见到人了？</p><p>她说，见到了。</p><p>她说，我在 ICU 外面站着，隔一层玻璃。</p><p>她说，她不睁眼。</p><p>她说，我在那个玻璃前面站了很久。</p><p>我说，她认得你吗。</p><p>她隔了很久。</p><p>这一句她隔的时间，比&quot;我阿婆中风了&quot;那一句还长。</p><p>然后她说。</p><p>她说，昨天下午医生让她睁一次眼。</p><p>她说，她睁了一下。</p><p>她说，我妈把我推前面，我妈说，妈，谁回来了。</p><p>她说，阿婆看我。</p><p>她说，她看了我十秒钟。</p><p>她说，她讲了一句话。</p><p>我说，讲的什么。</p><p>她说，她说，你怎么这么瘦。</p><p>我看到这一句，坐在椅子上，半天动不了。</p><p>她说，她不认得我。</p><p>她说，她喊的是我妈那一辈的人，她那天盯着我看了十秒，说的是&quot;你怎么这么瘦&quot;。</p><p>她说，可是她那一句，是我这一辈子听过的最准的一句。</p><p>她说，她脑子里现在没有我这个人。</p><p>她说，她的身体记得我瘦。</p><p>她说，我从八岁到十六岁，她每年给我两百。</p><p>她说，她是从她那个铁盒子里拿的，她不敢当面给，她给我都是在我走的时候塞我书包侧袋。</p><p>她说，我那八百块我一分没花。</p><p>我说，那你去哪儿都带着？</p><p>她说，我上大学带着。</p><p>她说，我那三年在高中旁边租的那个单间，第一个月的押金就是她从那个盒子里拿的五百。</p><p>她说，我妈不知道。</p><p>她说，我妈那时候不给我钱，我妈说你要什么你说，但是我们不能惯你。</p><p>她说，阿婆给的时候什么都不问。</p><p>她说，她给我钱那天她只说一句，她说&quot;你买点你爱吃的&quot;。</p><p>她说，我这一辈子只有一个人给我东西是不问我有没有用的。</p><p>她说，就是她。</p><p>她说，现在我一年能挣她那个盒子的三十倍。</p><p>她说，她躺在那儿，她不认得钱，也不认得我。</p><p>我那天下午没去实验室。</p><p>我给我妈打了一个电话，我说我们家那个铁盒子还在不在。</p><p>我妈说在，你要干什么。</p><p>我说，我看看。</p><p>我妈说，你要钱你说话。</p><p>我说，我不要钱。</p><p>我说，我就想知道奶奶那个盒子里现在还放着什么。</p><p>我妈停了一下。</p><p>我妈说，放着你的出生证明，你小时候一颗牙，还有几块钱。</p><p>我说，几块。</p><p>我妈说，六块。</p><p>她说，你奶奶就留着那六块，我给她钱她都存着。</p><p>我那天夜里在宿舍，把这两件事摆在一起算。</p><p>她那边的六块，她这边的一万二。</p><p>一个人给一个人留六块钱，另一个人给另一个人花一万二回来看一张不认识她的脸。</p><p>我算出来我心里那股东西叫什么。</p><p>我不愿意写出来。</p><p>因为写出来它就更丑。</p><p>我说的是：我在算她为了一个不认得她的人花了一万二，而她跟我说过两次&quot;机票太贵了今年回不去&quot;。</p><p>第三天她上线，跟我说的第一句是——</p><p>她说，我今天在机场丢了一个包。</p><p>她说，里面有一支笔，两本笔记，还有一个充电头。</p><p>她说，那个充电头我这辈子买了三个都坏，我今天丢了第四个我居然不难受。</p><p>我说，那笔重要吗。</p><p>她说，那笔是我妹给我塞进行李箱的。</p><p>她说，她说姐你带着这个写字好看。</p><p>我说，那你回去买一支一模一样的。</p><p>她说，买不到，那个笔是三块钱一支的。</p><p>她说，我明天就飞回去了。</p><p>我说，你那两周。</p><p>她说，我请了十六天。</p><p>我说，超过两周他们就不留了。</p><p>她说，我知道。</p><p>我说，那你明年作品集——</p><p>她说，闻迟。</p><p>她说，你今天怎么这么爱算。</p><p>我说，我在帮你算。</p><p>她说，你帮我把这笔算清楚了吗。</p><p>我说，哪笔。</p><p>她说，我这一趟花的那笔。</p><p>她说，我告诉你，我不算。</p><p>她说，我要是算我就不来了。</p><p>她说，我来这一次我什么都没了，可是我看见她说我瘦了。</p><p>她说，我明年再挣，我后年再挣，我挣到能带她出来那一天。</p><p>她说，她那天说的&quot;你怎么这么瘦&quot;，我要让她以后天天能说出这句。</p><p>她说，她说得出这句就说明她还在。</p><p>我看完了。</p><p>我说，好。</p><p>她说，你别&quot;好&quot;。</p><p>她说，你现在这个&quot;好&quot;，是你把话收起来了。</p><p>我说，我是觉得你说得对。</p><p>她说，你说得不对。</p><p>她说，你觉得我这次做的事，跟你想的那件事不一样。</p><p>我说，没有。</p><p>她说，你有。</p><p>她说，你从我说一万二开始就变了，你后来问我&quot;你请两周他们不留你&quot;的时候，你其实是在看我值不值。</p><p>她说，我不值。</p><p>她说，你算不清我这一趟。</p><p>她说，你算得清我就不给你算了。</p><p>我那天没有再回。</p><p>她那晚十一点二十下线。</p><p>第二天她上线，第一条是：</p><p>她说，我那个室友把我那盆绿萝浇死了。</p><p>她说，我回来一看，土是稀的。</p><p>她说，我说我养了两年。</p><p>她说，她说她不知道。</p><p>我说，那你再买一盆。</p><p>她说，我不想买。</p><p>她说，我今天不想再买任何东西。</p>',159)])])}const l=t(a,[["render",q]]);export{d as __pageData,l as default};
